import json, re
r = await web_search({"query": "stock market today live updates PCE inflation October core 3.3% GDP revised Nasdaq futures"})
if isinstance(r,str): r=json.loads(r)
for x in r:
    if not isinstance(x,dict): continue
    c = x.get("content") or ""
    print("##", x.get("title"), "|", x.get("url"), "|", x.get("page_age"))
    for m in re.finditer(r"[^.]*\b(PCE|Bowman|tariff)[^.]*\.", c):
        s = m.group(0).strip().replace("\n"," ")
        if len(s) > 40: print("  -", s[:300])

    print()
